import crossTierConstants from './cross-tier-constants.mjs';
import geohashPrecisionParity from './geohash-precision-parity.mjs';
import senderCountOffset from './sender-count-offset.mjs';

test('geohash-precision-parity: quiet on the real repo', () => {
  assert.deepEqual(geohashPrecisionParity.run(realCtx()), []);
});

// The sender seed lives in recipients.ts, the offset in index.ts; the fixtures
// vary each half independently, which is exactly how the pair breaks in life.
const RECIPIENTS_TS = (seed) => `
export function selectRecipients(candidates, center, radiusM, nowMs, senderUid) {
  const recipients: Recipient[] = ${seed};
  for (const candidate of candidates) {
    recipients.push({ uid: candidate.uid, distanceM: 0, isOwn: false });
  }
  return recipients;
}
`;
const SEEDED = '[{ uid: senderUid, distanceM: 0, isOwn: true }]';

const INDEX_TS = (countExpr) => `
/** Response: { messageId: string, recipientCount: number } (count excludes sender) */
const recipients = selectRecipients(candidates, [lat, lng], radiusM, nowMs, uid);
const recipientCount = ${countExpr};
await messageRef.set({ text, recipientCount });
return { messageId: messageRef.id, recipientCount };
`;

const senderFiles = (seed, countExpr) => ({
  'firebase/functions/src/recipients.ts': RECIPIENTS_TS(seed),
  'firebase/functions/src/index.ts': INDEX_TS(countExpr),
});

test('sender-count-offset: fires when the count stops subtracting the seeded sender', () => {
  const findings = senderCountOffset.run(ctxOf(senderFiles(SEEDED, 'recipients.length')));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].file, 'firebase/functions/src/index.ts');
  assert.equal(findings[0].line, 4);
  assert.match(findings[0].what, /seeds the sender into the list .* but recipientCount subtracts 0/);
  assert.equal(findings[0].severity, 'blocking');
});

test('sender-count-offset: fires when the sender seed goes away but the offset stays', () => {
  const findings = senderCountOffset.run(ctxOf(senderFiles('[]', 'recipients.length - 1')));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /no longer seeds the sender into the list/);
});

test('sender-count-offset: quiet when the seed and the offset agree', () => {
  assert.deepEqual(senderCountOffset.run(ctxOf(senderFiles(SEEDED, 'recipients.length - 1'))), []);
});

test('sender-count-offset: quiet when neither seeds nor subtracts', () => {
  assert.deepEqual(senderCountOffset.run(ctxOf(senderFiles('[]', 'recipients.length'))), []);
});

test('sender-count-offset: fires when the recipient list initializer moves out of reach', () => {
  const files = senderFiles(SEEDED, 'recipients.length - 1');
  files['firebase/functions/src/recipients.ts'] =
    RECIPIENTS_TS(SEEDED).replace(/const recipients[^;]+;/, 'const recipients = seed(senderUid);');
  const findings = senderCountOffset.run(ctxOf(files));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /no `recipients` list initializer found/);
});

test('sender-count-offset: fires when no count is derived from the list length', () => {
  const files = senderFiles(SEEDED, 'recipients.length - 1');
  files['firebase/functions/src/index.ts'] = INDEX_TS('countOf(recipients)');
  const findings = senderCountOffset.run(ctxOf(files));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /no recipientCount derived from a list length/);
});

test('sender-count-offset: quiet on the real repo', () => {
  assert.deepEqual(senderCountOffset.run(realCtx()), []);
});

